const input = $input.first().json.body || $input.first().json;
const properties = Array.isArray(input.properties) ? input.properties.slice(0, 500).map((p, i) => ({ ref: p.ref || `property-${i + 1}`, status: p.status, occupancy: Number(p.occupancy || 0), capacity: Number(p.capacity || 0), openLeads: Number(p.openLeads || 0), staleLeadCount: Number(p.staleLeadCount || 0), pendingApprovals: Number(p.pendingApprovals || 0), openTasks: Number(p.openTasks || 0), overdueTasks: Number(p.overdueTasks || 0), periodRevenue: Number(p.periodRevenue || 0), periodCosts: Number(p.periodCosts || 0), dataAsOf: p.dataAsOf || null })) : [];
const totals = properties.reduce((a, p) => { a.properties++; a.occupied += p.occupancy; a.capacity += p.capacity; a.openLeads += p.openLeads; a.staleLeadCount += p.staleLeadCount; a.pendingApprovals += p.pendingApprovals; a.overdueTasks += p.overdueTasks; a.revenue += p.periodRevenue; a.costs += p.periodCosts; return a; }, { properties: 0, occupied: 0, capacity: 0, openLeads: 0, staleLeadCount: 0, pendingApprovals: 0, overdueTasks: 0, revenue: 0, costs: 0 });
const prompt = `Prepare an operational review of these aggregated property portfolio metrics. Highlight data gaps, trends and items for authorized human follow-up. Do not make property valuations, legal/compliance conclusions, tenant decisions, approve leads or payments, or send communications. Do not attempt to identify residents. Return JSON: executiveSummary (string), exceptions (array), suggestedChecks (array), dataLimitations (array).
TOTALS=${JSON.stringify(totals)}
PROPERTY_METRICS=${JSON.stringify(properties)}`;
return [{ json: { totals, prompt } }];

const response = $input.first().json;
const totals = $('Aggregate Portfolio Metrics').first().json.totals;
let review; try { review = JSON.parse(response.candidates[0].content.parts[0].text); } catch { review = { executiveSummary: 'AI review unavailable; inspect the source metrics.', exceptions: [], suggestedChecks: [], dataLimitations: ['Could not parse AI response.'] }; }
return [{ json: { status: 'review_ready', totals, review, requiresHumanReview: true, recordsChanged: false } }];
